// Convert binary image buffer to clean Base64 for Gemini Vision
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Image = binaryData.toString('base64');

const triggerNode = $('Has Receipt Photo?').first().json;
const userCaption = triggerNode.message?.caption || '';

const prompt = `You are the TravelTokyo AI Expense Parser for a 7-day Tokyo trip.\nAnalyze this image and user caption: '${userCaption}'.\n\nTASK 1: Determine if this is an actual monetary receipt / paid transaction OR a non-expense item (scenery photo, selfie, general chat, travel document without price).\nTASK 2: If it is an expense, extract all transaction details.\n\nOutput strictly valid JSON matching this schema:\n{\n  "is_expense": boolean,\n  "non_expense_reason": string (e.g. 'Scenery photo', 'Selfie', 'No price on photo'),\n  "title": string (Merchant name / item description, e.g. '7-Eleven Asakusa Snacks', 'Ichiran Ramen', 'Tokyo Disney Popcorn'),\n  "amount": number (Total in JPY integer, e.g. 1800),\n  "currency": "JPY",\n  "category": string (Must be ONE of: 'food', 'transport', 'shopping', 'tickets', 'hotel', 'flights', 'documents', 'other'),\n  "paymentMethod": string (Must be ONE of: 'Cash', 'BDO JCB', 'BDO Mastercard', 'RCBC Visa', 'GCash', 'MariBank', 'UnionBank Visa', 'Other Card / Wallet'),\n  "date": string (YYYY-MM-DD format),\n  "status": "paid",\n  "notes": string,\n  "needs_clarification": boolean,\n  "clarification_question": string\n}\n\nPayment Methods:\n- '現金' or cash -> 'Cash'\n- 'JCB' -> 'BDO JCB'\n- 'Mastercard' or 'MC' -> 'BDO Mastercard'\n- 'VISA' -> 'RCBC Visa'\n- Default to 'Cash' if unstated.\n\nNever fabricate unreadable totals. If amount is cut off or illegible, set needs_clarification=true and formulate a clarification_question.`;

const payload = {
  contents: [
    {
      parts: [
        { text: prompt },
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image
          }
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1,
    responseMimeType: 'application/json'
  }
};

return [{ json: { geminiPayload: payload } }];

// Prepare text payload for Gemini Text Parser
const userText = $json.message?.text || '';

const prompt = `You are the TravelTokyo AI Expense Parser for a 7-day Tokyo trip.
Analyze this text message: '${userText}'.

TASK 1: Determine if this is a real paid expense transaction (e.g. 'Ramen 1500 jpy cash', 'suica reload 2000 bdo', 'donki shopping 4500 rcbc') OR a non-expense conversational message (e.g. 'Good morning', 'We arrived at Asakusa', 'Where is the station?').
TASK 2: If it is an expense, extract all details.

Output strictly valid JSON matching this schema:
{
  "is_expense": boolean,
  "non_expense_reason": string (if not an expense),
  "title": string (Merchant name / item description),
  "amount": number (Total in JPY integer),
  "currency": "JPY",
  "category": string (Must be ONE of: 'food', 'transport', 'shopping', 'tickets', 'hotel', 'flights', 'documents', 'other'),
  "paymentMethod": string (Must be ONE of: 'Cash', 'BDO JCB', 'BDO Mastercard', 'RCBC Visa', 'GCash', 'MariBank', 'UnionBank Visa', 'Other Card / Wallet'),
  "date": string (YYYY-MM-DD format),
  "status": "paid",
  "notes": string,
  "needs_clarification": boolean,
  "clarification_question": string
}

Payment Methods:
- cash -> 'Cash'
- bdo jcb / jcb -> 'BDO JCB'
- bdo / mastercard -> 'BDO Mastercard'
- rcbc / visa -> 'RCBC Visa'
- gcash -> 'GCash'
- maribank -> 'MariBank'
- unionbank -> 'UnionBank Visa'
- default: 'Cash'

If this is a non-expense conversational message, set is_expense=false.`;

const payload = {
  contents: [
    {
      parts: [
        { text: prompt }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1,
    responseMimeType: 'application/json'
  }
};

return [{ json: { geminiPayload: payload } }];

// 1. Extract JSON from Gemini Response
let rawText = "{}";
const res = $input.first().json;

if (res.candidates && res.candidates[0]?.content?.parts[0]?.text) {
  rawText = res.candidates[0].content.parts[0].text;
} else if (res.text) {
  rawText = res.text;
}

let parsed = {};
try {
  const clean = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    is_expense: false,
    non_expense_reason: "Could not parse AI output format."
  };
}

// 2. Chat Info
const triggerData = $("Telegram Trigger").first().json;
const chatId = triggerData.message?.chat?.id || triggerData.message?.from?.id;
const messageId = triggerData.message?.message_id;
const senderName = triggerData.message?.from?.first_name || "Traveler";

// 3. Non-Expense Filtering
if (parsed.is_expense === false) {
  return [{
    json: {
      type: "non_expense",
      chatId: chatId,
      messageId: messageId,
      reason: parsed.non_expense_reason || "Non-expense message or photo.",
      senderName: senderName
    }
  }];
}

// 4. Duplicate Detection (In-Memory Fingerprint)
const fxRate = 2.70;
const amountJPY = parseInt(parsed.amount, 10) || 0;
const amountPHP = Math.round(amountJPY / fxRate);
const transactionDate = parsed.date || new Date().toISOString().split('T')[0];
const title = (parsed.title || "Tokyo Expense").trim();

const fingerprint = `${title.toLowerCase().replace(/[^a-z0-9]/g, '')}_${amountJPY}_${transactionDate}`;

const staticData = $getWorkflowStaticData('global');
staticData.processedFingerprints = staticData.processedFingerprints || [];

if (amountJPY > 0 && staticData.processedFingerprints.includes(fingerprint)) {
  return [{
    json: {
      type: "duplicate",
      chatId: chatId,
      messageId: messageId,
      title: title,
      amount: amountJPY,
      date: transactionDate,
      senderName: senderName
    }
  }];
}

// Register fingerprint (keep last 50 entries)
if (amountJPY > 0) {
  staticData.processedFingerprints.push(fingerprint);
  if (staticData.processedFingerprints.length > 50) {
    staticData.processedFingerprints.shift();
  }
}

// 5. Clarification Handling
if (parsed.needs_clarification || amountJPY <= 0) {
  return [{
    json: {
      type: "clarification",
      chatId: chatId,
      messageId: messageId,
      clarification_question: parsed.clarification_question || `Found receipt for "${title}" but the total Yen amount is missing or unclear. How much was the total in JPY?`,
      senderName: senderName
    }
  }];
}

// 6. Valid TravelTokyo Expense Record
const expenseRecord = {
  type: "valid_expense",
  id: `paid-${Date.now()}`,
  title: title,
  amount: amountJPY,
  currency: "JPY",
  category: parsed.category || "food",
  paymentMethod: parsed.paymentMethod || "Cash",
  date: transactionDate,
  status: "paid",
  notes: parsed.notes || "Logged via Gemini Telegram receipt bot",
  convertedAmountPHP: amountPHP,
  chatId: chatId,
  messageId: messageId,
  senderName: senderName
};

return [ { json: expenseRecord } ];

